insert into public.reference_passages
  (id, source_id, branch, personnel_category, occupation_code, occupation_title, section_type, rank_band, components, heading, chapter, body, body_sha256, pdf_page_start, pdf_page_end, printed_page, sort_order, effective_from, effective_to, cumulative, skill_level)
values
  ('872a4129-3ce3-5c16-b9b8-efe16b208a8f', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-1..O-2', null, 'Lieutenant development — overview', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'FA 49 has no lieutenant authorizations.', '48f1eaec3ae557e04d6611a847ce5e217e6c83d5a5dd6cc10a9811884f787f20', 2, 2, null, 0, null, null, false, null),
  ('24514e1b-c852-5d9f-b2b5-6a2db569988d', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-3..O-4', null, 'Captain/junior major development. Officers are selected for FA 49 as captains around their 6th year — overview', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'of service. Before transitioning to FA 49, officers will be fully qualified as a captain in their basic branch, having completed their respective Captain’s Career Course and an appropriate key development assignment.', 'a52b42086aa80fe6a6748be797dfad165bb05cd200e0c049df6867062afa3659', 2, 2, null, 1, null, null, false, null),
  ('e63942ac-e916-58f1-86ce-ae224661dcaf', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'training', 'O-3..O-4', null, 'Captain/junior major development. Officers are selected for FA 49 as captains around their 6th year — Education', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Prior to their first ORSA assignment, officers are required to either complete initial ORSA training via ORSA-MAC or complete a graduate degree in a field approved by the proponent. Officers completing ORSA-MAC are still eligible to earn a graduate degree through ACS.', '09f70bffa2957d07fe7555e4283dccd8ea673edb8e19c55ed0413e6bed743b90', 2, 2, null, 2, null, null, false, null),
  ('2a576736-94dd-57a9-9acb-e4ad6410f95e', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'assignments', 'O-3..O-4', null, 'Captain/junior major development. Officers are selected for FA 49 as captains around their 6th year — Key developmental assignments', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'None.', '903ea500e7ccf842c1312b6c2f964e3e98ff146456cecec717e9a0e122bf735f', 2, 2, null, 3, null, null, false, null),
  ('94f4f007-cac1-5b6f-a933-6e264c917cca', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-3..O-4', null, 'Captain/junior major development. Officers are selected for FA 49 as captains around their 6th year — Developmental and broadening assignments', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Upon completion of initial ORSA training FA 49 officers will enter into their first assignment with the goal of mastering their analytic skills. These assignments are typically in organizations that have senior FA 49 officers available to coach, teach, and mentor the new FA 49 officers. Because FA 49 officers are selected as senior captains, the combination of their basic branch assignments with their initial ORSA assignment (defined above) provides a sufficiently broad developmental experience.', '664ea0dbee784fbb72ec8a812002e6aac36ca61f0af89a9e31c38d20780443f0', 3, 3, null, 4, null, null, false, null),
  ('f022d030-7812-5f81-81fd-2776103cd798', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'self_development', 'O-3..O-4', null, 'Captain/junior major development. Officers are selected for FA 49 as captains around their 6th year — Self-development', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Officers with a non-ORSA related graduate degree or officers whose professional timeline does not support a fully funded ACS program are encouraged to pursue an advanced degree through other means. Officers should maintain and build upon their technical and professional skillsets though programs like the Continuing Education Program sponsored by the FA49 proponent, relevant military courses (e.g., the Force Management course), and involvement in professional organizations such as the Military Operations Research Society (MORS), the Army Operations Research Society (AORS), and the Institute for Operations Research and Management Sciences (INFORMS).', '0465bdd89edee6fb348c47b4aaf73d4998d64a1fd4484b91e3bbd9231e039b03', 3, 3, null, 5, null, null, false, null),
  ('5c721fcd-9c14-596b-bc21-335577143327', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-3..O-4', null, 'Captain/junior major development. Officers are selected for FA 49 as captains around their 6th year — Desired experience', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Upon completion of their first FA 49 assignment, officers should have mastered their analytic skills and be capable of applying those skills in support of operational, generating, or Headquarters/Department analytic efforts.', 'f8bd70e5577a3ad22f452d61cc6d633a40424bdd7a52d5466e92f5c69a27565f', 3, 3, null, 6, null, null, false, null),
  ('53ce2636-9668-5401-80b6-aa091963c15c', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'training', 'O-4', null, 'Major development — Education', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Majors should continue to pursue a master’s degree in an operations research related field. Senior Majors that have displayed high performance and potential that have completed a master’s degree are encouraged to pursue an advanced degree in a doctorate program approved by the proponent. Majors are required to complete ILE qualification, which consists of successful completion of ILE Common Core and the FA49 Qualification Course. Officers are encouraged to complete ILE Common Core at a satellite campus or via distance learning, even if selected for resident ILE.', '4c08238550ea6f9b9941cfb2b663055e4e9248bc1d86e3431f28c030596876e6', 3, 3, null, 7, null, null, false, null),
  ('c214f8c3-b807-58f5-be92-b3013568741b', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'assignments', 'O-4', null, 'Major development — Key developmental assignments', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'None.', '903ea500e7ccf842c1312b6c2f964e3e98ff146456cecec717e9a0e122bf735f', 3, 3, null, 8, null, null, false, null),
  ('6ae084ba-86a6-5a8e-8d51-edefc2fe29e6', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-4', null, 'Major development — Developmental and broadening assignments', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', '(a) After an officer’s initial FA 49 assignment, select officers should seek assignments that support the operating force. These officers can expect an assignment to a Division or Corps headquarters, Army Service Component Command, Combatant Command, Special Operations or a tasking as an individual augmentee to a deployed organization.
(b) In subsequent assignments, officers can also expect to serve on high-level headquarters staffs as Action Officers, and in units with a lower density of FA 49 officers. Officers should also seek opportunities in technical domains such as Cyber, Special Operations, Networks, and Intelligence.', 'e441167d8a5dcbe2703324263008401722690a800a9e16afc2bb080b25fb6a0e', 3, 3, null, 9, null, null, false, null),
  ('3bd06ec7-deb1-546e-ad04-471f34b0f500', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'self_development', 'O-4', null, 'Major development — Self-development', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Officers with a non-ORSA related graduate degree or officers whose professional timeline does not support a fully funded ACS program are encouraged to pursue an advanced degree through other means. Additionally, officers should continue to maintain and build upon their technical and professional skillsets though programs like the Continuing Education Program sponsored by the FA49 proponent, relevant military courses such as (e.g., the Force Management course), and involvement in professional organizations such as MORS, AORS, and INFORMS.', '41b1290be909842d6ccd5e5dc9d83290e5ce1dc8778cb1052541a27ea641b24b', 3, 3, null, 10, null, null, false, null),
  ('7b0a96aa-9d2e-58d9-876e-5c8ca08e9c42', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-4', null, 'Major development — Desired experience', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'The FA 49 officers should have mastered ORSA skills, be operationally relevant, and be prepared to serve as an ORSA leader.', '0076217cbe748f148f4e886b83ba71820360cc63757914d5d7bfe932344720b9', 3, 3, null, 11, null, null, false, null),
  ('f084ad13-fd39-51d6-aa34-57ec771e94cd', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'training', 'O-5', null, 'Lieutenant colonel development — Education', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Lieutenant colonels that have displayed high performance and potential that have completed a master’s degree in an ORSA related field are encouraged to pursue an advanced degree in a doctorate program approved by the proponent. A select number of lieutenant colonels will have the opportunity to attend SSC.', '9a889007f625009f47cc2cc53e5d2e2e7d260685ebf1f74f61f1227421a9e087', 3, 3, null, 12, null, null, false, null),
  ('ef3618d8-3100-5b66-a195-f54a30f55924', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'assignments', 'O-5', null, 'Lieutenant colonel development — Key developmental assignments', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Select FA 49 lieutenant colonel billets are designated as Key Nominative Billets (KNB). KNB billets are key and strategic positions across the ORSA enterprise that serve to develop well rounded FA 49 Colonels with a depth of knowledge and experience capable of successfully serving in the Army’s most demanding positions.', '609f683a76b2248000b40768ac919ba3bedd520224dd3bf6a2ec3c119bf7f3a0', 3, 3, null, 13, null, null, false, null),
  ('43821701-8a6b-5861-a1cb-2573c0105003', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-5', null, 'Lieutenant colonel development — Developmental and broadening assignments', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'The FA 49 lieutenant colonels are expected to serve in positions of increased responsibility and leadership in the ORSA community, particularly on the Army Staff, Joint billets, and ACOMs. Officers should also seek assignments that broaden their Operations Research/ Systems Analysis skill and experience set.', 'b522b5c59a3b75fe8531913fa1bf4f488912ac7573046cbcedecf954aa06b659', 3, 4, null, 14, null, null, false, null),
  ('a66d1f92-cf52-56ab-9270-9a22ab123c7f', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'self_development', 'O-5', null, 'Lieutenant colonel development — Self-development', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Lieutenant colonels should continue to pursue a master’s degree in a program approved by the proponent. Additionally, officers should continue to maintain and build upon their technical and professional skillsets though programs like the Continuing Education Program sponsored by the FA49 proponent, relevant military courses such as e.g., the Force Management course), and involvement in professional organizations such as MORS, AORS, and INFORMS.', '84897528d3589e4d6b8bbd26da367f771d75064d22ea6a0e204531ea4abbccaf', 4, 4, null, 15, null, null, false, null),
  ('4ea7aded-2f39-5b52-9816-3eeced86ed8e', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-5', null, 'Lieutenant colonel development — Desired experience', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'The ORSA lieutenant colonels should serve as leaders in the ORSA community and on high-level staffs such as the Army Staff, Joint Staff, Office of the Secretary of Defense, and Combatant Commands.', 'b79f68685913e3ea77a9e38460aebc3d1cef8023f369a9bc3757ebca4b810875', 4, 4, null, 16, null, null, false, null),
  ('275c21e3-a671-592e-a402-37765fcb57a3', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'training', 'O-6', null, 'Colonel development — Education', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'All FA 49 colonels are required to have completed a master’s degree in an operations research related field approved by the proponent. A select number of colonels will have the opportunity to attend a resident SSC. All other colonels are encouraged to complete the Army War College Distance Education Program.', '9d7d8fcfd9d3e334f78890cf60dfea5439c9cc8e042b4add5dbd8f5a76cc475a', 4, 4, null, 17, null, null, false, null),
  ('a673aedf-08a0-5050-be67-3c89b2075870', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'assignments', 'O-6', null, 'Colonel development — Key developmental assignments', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'None.', '903ea500e7ccf842c1312b6c2f964e3e98ff146456cecec717e9a0e122bf735f', 4, 4, null, 18, null, null, false, null),
  ('70870e9e-b991-5010-813d-c98045a77cae', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-6', null, 'Colonel development — Developmental and broadening assignments', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'FA 49 colonels serve in a variety of positions across the Army and Department of Defense.', 'e342e92b27dc13df149a97dc17b6062dea971e4af4a2c545f3e188f735302152', 4, 4, null, 19, null, null, false, null),
  ('c5407f24-6448-5b0c-b98f-9fd751f07393', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'self_development', 'O-6', null, 'Colonel development — Self-development', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'Officers should continue to maintain and build upon their technical and professional skillsets though programs like the Continuing Education Program sponsored by the FA49 proponent, relevant military courses such as (e.g., the Force Management course), and involvement in professional organizations such as MORS, AORS, and INFORMS.', 'b347514864289cbbc84119b7ac810381775c35a5f141ee33c493b19540f49dee', 4, 4, null, 20, null, null, false, null),
  ('49863bd4-b392-5770-82dc-8906888b294a', 'e80d0bd9-9611-5be7-ad25-9f419ab57b25', 'Army', 'officer', '49A', 'OPERATIONS RESEARCH/SYSTEMS ANALYSIS', 'development', 'O-6', null, 'Colonel development — Desired experience', 'Operations Research/Systems Analysis Functional Area career pamphlet, DA PAM 600-3 chapter (1 June 2021)', 'FA 49 colonels are senior leaders across the ORSA enterprise and are strategic thinkers capable of leading analytically focused individuals, teams, and organizations at all echelons across the JIIM environment.', '9fb807d09f0faa0fb7ab8d193eae6c51fc88fb57fc8aedee3cbd6598a7705567', 4, 4, null, 21, null, null, false, null);
